package com.vaultorandroid

import android.content.*
import android.util.AtomicFile
import androidx.core.content.FileProvider
import org.json.*
import java.io.*
import java.security.MessageDigest
import java.util.UUID
import java.util.concurrent.Executors
import java.util.zip.*
import javax.net.ssl.HttpsURLConnection

/** Derivative export artifacts only. Independent of downloads, Reviews and original import bytes. */
class VaultorExports(private val ctx:Context,private val companions:VaultorCompanions,
 private val connection:(JSONObject,String,String)->HttpsURLConnection,
 private val admission:(JSONObject)->Unit,private val reviews:()->List<JSONObject>,private val changed:()->Unit={},private val localIdentity:(JSONObject)->Unit={}) {
 companion object {const val MAX=256L*1048576;private val lock=Any();private val worker=Executors.newSingleThreadExecutor();private val running=java.util.concurrent.ConcurrentHashMap.newKeySet<String>()}
 private val root=File(ctx.noBackupFilesDir,"exports-v1").apply {check(mkdirs()||isDirectory)}
 private val outputPrefs=ctx.getSharedPreferences("export-handoff-v1",Context.MODE_PRIVATE)
 private fun file(id:String)=File(root,UUID.fromString(id).toString()+".json")
 private fun item(id:String)=synchronized(lock){JSONObject(String(AtomicFile(file(id)).readFully(),Charsets.UTF_8))}
 private fun save(row:JSONObject)=synchronized(lock){val af=AtomicFile(file(row.getString("id")));val out=af.startWrite();try{out.write(row.toString().toByteArray());af.finishWrite(out)}catch(e:Exception){af.failWrite(out);throw e};changed()}
 fun list():JSONArray=synchronized(lock){JSONArray(root.listFiles().orEmpty().filter {it.name.matches(Regex("[a-f0-9-]{36}\\.json"))}.map {item(it.name.removeSuffix(".json")).also {row->if(row.optString("state")=="preparing"&&!running.contains(row.getString("id")))row.put("state","paused").put("detail","Interrupted preparation. Resume the same operation.")}}.sortedByDescending {it.optLong("at")})}
 private fun artifact(id:String)=File(root,UUID.fromString(id).toString()+".bin")
 private fun used()=root.listFiles().orEmpty().sumOf {it.length()}
 private fun room(extra:Long){require(extra>=0&&used()+extra<=MAX&&root.usableSpace>extra+16L*1048576){"Export storage is full (256 MiB). Remove a finished export; downloads and queues are retained."}}
 private fun hash(f:File):String{val digest=MessageDigest.getInstance("SHA-256");f.inputStream().use {i->val b=ByteArray(65536);while(true){val n=i.read(b);if(n<0)break;digest.update(b,0,n)}};return digest.digest().joinToString(""){"%02x".format(it)}}
 private fun guard(row:JSONObject){localIdentity(row.getJSONObject("source"));val current=item(row.getString("id"));require(current.getString("state")!="paused"){"Export paused. Retry the same operation."};require(!companions.isLocked(row.getString("scope"))){"Original source is locked. Export retained but unavailable."};if(!row.getBoolean("offline"))admission(row.getJSONObject("source"))}
 fun start(a:JSONObject):JSONObject {val scope=a.getString("scope");val parts=JSONArray(scope);require(parts.length()==3);(0..2).forEach {UUID.fromString(parts.getString(it))};val request=JSONObject(a.getJSONObject("request").toString());val ids=request.getJSONArray("ids");require(ids.length()<=100);for(i in 0 until ids.length())UUID.fromString(ids.getString(i));require(request.getInt("depth") in 0..3);val offline=a.optBoolean("offline");if(offline)require(request.getString("format") in listOf("partial","markdown")&&request.getString("scope") in listOf("resources","collection","downloaded")){"Full ZIP/PDF/Word requires a connected host"};request.put("generation",parts.getString(2));val row=JSONObject().put("version",1).put("id",UUID.randomUUID().toString()).put("scope",scope).put("source",JSONObject().put("hostId",parts.getString(0)).put("workspaceId",parts.getString(1)).put("generation",parts.getString(2))).put("label",a.optString("label").take(200)).put("request",request).put("offline",offline).put("at",System.currentTimeMillis()).put("state","preparing").put("detail",if(offline)"Preparing a clearly partial reading package" else "Preparing on the confirmed host");synchronized(lock){require(list().length()<8){"Eight retained exports reached. Remove a finished export first."};room(1048576);save(row)};resume(row.getString("id"));return row}
 fun resume(id:String):JSONObject {val row=item(id);if(row.optString("state")=="ready")return row;row.put("state","preparing").put("detail","Resuming the same captured export");save(row);if(running.add(id))worker.execute {try{val captured=item(id);guard(captured);for(interrupted in listOf(File(root,"$id.part"),artifact(id)))require(interrupted.delete()||!interrupted.exists()){"Could not clear interrupted derivative; source and operation retained"};if(captured.getBoolean("offline"))offline(captured)else online(captured)}catch(e:Exception){val current=item(id);if(current.getString("state")!="paused"){current.put("state","error").put("detail",(e.message?:"Export interrupted. Retry the same operation.").take(260));save(current)}}finally{running.remove(id)}};return row}
 fun pause(id:String){val row=item(id);row.put("state","paused").put("detail","Paused. Retry retains the same source and operation.");save(row)}
 fun remove(id:String){require(!running.contains(id)){"Pause and wait for the export before removal"};synchronized(lock){artifact(id).delete();File(root,"$id.part").delete();val shared=File(ctx.cacheDir,"media-share").listFiles().orEmpty().filter {it.name.startsWith("export-$id-")};shared.forEach {it.delete()};AtomicFile(file(id)).delete();changed()}}
 private fun call(row:JSONObject,path:String,method:String="GET",body:JSONObject?=null,retry:Int=0):JSONObject {guard(row);val c=connection(row.getJSONObject("source"),path,method);try{if(body!=null){c.doOutput=true;c.setRequestProperty("Content-Type","application/json");c.outputStream.use {it.write(body.toString().toByteArray())}};val status=c.responseCode;val bytes=(if(status in 200..299)c.inputStream else c.errorStream)?.use {it.readNBytes(1500001)}?:byteArrayOf();require(bytes.size<=1500000);val value=if(bytes.isEmpty())JSONObject() else JSONObject(String(bytes,Charsets.UTF_8));if(status==409&&value.optString("code") in listOf("WORKSPACE_BUSY","CONFLICT")&&retry<40){Thread.sleep(350);return call(row,path,method,body,retry+1)};companions.observeResponse(row.getJSONObject("source"),path,status,value);require(status in 200..299){value.optString("detail","Host refused export ($status). Original source and operation retained.").take(200)};guard(row);return value}finally{c.disconnect()}}
 private fun online(row:JSONObject){val id=row.getString("id");val request=row.getJSONObject("request");val path="/companions/exports/$id";require(call(row,"/companions/export-capabilities").optInt("version")==1){"Update this host for companion exports"};var receipt=call(row,path,"PUT",request);var n=0;while(receipt.getJSONObject("operation").getString("status") in listOf("QUEUED","RUNNING","CLEANUP")){require(n++<1200){"Host preparation remains pending. Retry the same operation."};Thread.sleep(500);receipt=call(row,path+"?generation="+request.getString("generation"))};require(receipt.getInt("version")==1&&receipt.getString("id")==id&&receipt.getString("generation")==request.getString("generation"));val echoed=receipt.getJSONObject("request");for(k in listOf("generation","scope","format","depth"))require(echoed.optString(k)==request.optString(k)){"Export receipt differs"};require(echoed.getJSONArray("ids").toString()==request.getJSONArray("ids").toString());val op=receipt.getJSONObject("operation");if(receipt.optJSONObject("coverage")!=null)row.put("coverage",receipt.getJSONObject("coverage"));require(op.getString("status")=="SUCCEEDED"){op.optString("detail","Host export did not complete")};val size=receipt.getLong("bytes");val expected=receipt.getString("sha256");require(size in 1..MAX&&expected.matches(Regex("[a-f0-9]{64}"))){"Host export exceeds the256MiB device bound or has no checksum"};room(size);row.put("receipt",receipt).put("detail","Downloading and verifying host artifact");save(row);val part=File(root,"$id.part");part.delete();val c=connection(row.getJSONObject("source"),path+"/download?generation="+request.getString("generation"),"GET");try{val status=c.responseCode;if(status!=200){val problem=c.errorStream?.use{it.readNBytes(16385)}?:byteArrayOf();if(problem.size<=16384)companions.observeResponse(row.getJSONObject("source"),path+"/download",status,runCatching{JSONObject(String(problem))}.getOrDefault(JSONObject()))};require(status==200&&c.getHeaderField("X-Vaultor-SHA256")==expected);var count=0L;c.inputStream.use {input->FileOutputStream(part).use {out->val buffer=ByteArray(65536);while(true){guard(row);val read=input.read(buffer);if(read<0)break;count+=read;require(count<=size);room(read.toLong());out.write(buffer,0,read)};out.fd.sync()}};require(count==size&&hash(part)==expected){"Export failed integrity verification. Retry the same operation."}}finally{c.disconnect()};guard(row);check(part.renameTo(artifact(id)));row.put("state","ready").put("sha256",expected).put("bytes",size).put("filename",safeName(op.optString("filename","export.zip"))).put("mime",op.optString("mediaType","application/zip").substringBefore(';').trim()).put("detail","Verified host export ready. Save/Share requires your choice.");save(row)}
 private fun safeName(raw:String)=raw.replace(Regex("[\\\\/\\p{Cntrl}:*?\"<>|]"),"_").take(180).ifBlank {"export.zip"}
 private fun original(dir:File,e:JSONObject,kind:String):File? {val descriptor=e.optJSONObject(kind)?:return null;if(descriptor.optString("state")!="available")return null;val extension=if(kind=="document")"json" else "bin";val f=File(dir,e.getString("id")+"."+extension);require(f.length()==descriptor.getLong("bytes")&&hash(f)==descriptor.getString("sha256")){"Downloaded source failed integrity. Refresh it before exporting."};return f}
 private fun offline(row:JSONObject){val id=row.getString("id");val part=File(root,"$id.part");part.delete();companions.exportSnapshot(row.getString("scope")){metadata,all,dir->
  val request=row.getJSONObject("request");val selected=linkedSetOf<String>();val seeds=request.getJSONArray("ids");if(request.getString("scope")=="downloaded")selected.addAll(all.map {it.getString("id")})else if(request.getString("scope")=="collection"){val collections=metadata.getJSONObject("organization").getJSONArray("collections");for(i in 0 until collections.length()){val c=collections.getJSONObject(i);if((0 until seeds.length()).any {seeds.getString(it)==c.getString("id")}){val members=c.getJSONArray("resources");for(j in 0 until members.length())selected.add(members.getString(j))}}}else for(i in 0 until seeds.length())selected.add(seeds.getString(i));require(selected.isNotEmpty()){ "No selected downloaded resources" }
  val byId=all.associateBy {it.getString("id")};val included=linkedMapOf<String,JSONObject>();val omissions=JSONArray();var frontier=selected.toSet();for(depth in 0..request.getInt("depth")){val next=linkedSetOf<String>();for(rid in frontier){if(included.containsKey(rid))continue;val e=byId[rid];if(e==null||e.optString("state")!="available"){omissions.put(JSONObject().put("id",rid).put("reason","not downloaded or unavailable"));continue};val note=e.getString("type")=="note";if(original(dir,e,if(note)"document" else "binary")==null){omissions.put(JSONObject().put("id",rid).put("reason",if(note)"document unavailable" else "original not downloaded"));continue};require(included.size<500){"Partial export exceeds500 resources"};included[rid]=e;val refs=e.optJSONArray("references")?:JSONArray();for(n in 0 until refs.length()){val target=refs.getString(n);if(depth<request.getInt("depth"))next.add(target)else {require(omissions.length()<20000){"Too many omitted links"};omissions.put(JSONObject().put("id",target).put("reason","beyond selected depth"))};require(next.size<=500){"Linked selection exceeds500 resources"}}};frontier=next}
  require(included.isNotEmpty()){ "None of the selected original content is downloaded" };val coverage=JSONObject().put("version",1).put("kind","vaultor-partial").put("capturedAt",java.time.Instant.ofEpochMilli(metadata.getLong("at")).toString()).put("depth",request.getInt("depth")).put("inventory",JSONArray(included.values.map {JSONObject().put("id",it.getString("id")).put("title",it.getString("title")).put("type",it.getString("type"))})).put("omissions",JSONArray((0 until omissions.length()).map {omissions.getJSONObject(it)}.filter {it.getString("id") !in included})).put("reviewCoverage","acknowledged device captures only; other host Reviews unavailable offline").put("provenanceCoverage","hidden converted-import originals not present in reading checkpoints");val resources=JSONArray();val tags=linkedMapOf<String,JSONObject>();val binaries=linkedMapOf<String,File>();var total=0L;var jsonBytes=0L
  for((rid,e) in included){guard(row);val note=e.getString("type")=="note";val f=original(dir,e,if(note)"document" else "binary")!!;require(f.length()<=if(note)1048576 else 64L*1048576);total+=f.length();jsonBytes+=if(note)f.length()else e.toString().length*2L;require(jsonBytes<=16*1048576){"Selected structured metadata exceeds16MiB; export a smaller selection"};require(total<=MAX);val memberships=e.optJSONArray("tags")?:JSONArray();val tagIds=JSONArray();for(n in 0 until memberships.length()){val t=memberships.getJSONObject(n);tags[t.getString("id")]=t;tagIds.put(t.getString("id"))};val r=JSONObject().put("id",rid).put("type",e.getString("type")).put("title",e.getString("title")).put("content",if(note)JSONObject(f.readText())else JSONObject.NULL).put("mimeType",e.opt("mimeType")?:JSONObject.NULL).put("size",if(note)JSONObject.NULL else f.length()).put("createdAt",e.getString("updatedAt")).put("updatedAt",e.getString("updatedAt")).put("lastOpenedAt",JSONObject.NULL).put("tags",tagIds).put("binary",if(note)JSONObject.NULL else "files/$rid");resources.put(r);if(!note)binaries["files/$rid"]=f}
  val org=metadata.getJSONObject("organization");val collections=org.getJSONArray("collections");val subset=JSONArray();for(n in 0 until collections.length()){val c=collections.getJSONObject(n);val members=c.getJSONArray("resources");val kept=JSONArray((0 until members.length()).map {members.getString(it)}.filter {it in included});if(kept.length()>0)subset.put(JSONObject().put("id",c.getString("id")).put("name",c.getString("name")).put("favorite",c.optBoolean("favorite")).put("resources",kept))}
  val portableReviews=JSONArray();for(capture in reviews()){val source=capture.getJSONObject("source");val sourceKey=JSONArray(listOf(source.getString("hostId"),source.getString("workspaceId"),source.getString("generation"))).toString();if(sourceKey!=row.getString("scope"))continue;val delivery=capture.optJSONObject("delivery")?:continue;if(delivery.optString("state")!="synced")continue;val receipt=delivery.optJSONObject("receipt")?:continue;val body=capture.getJSONObject("body");if(body.getString("resourceId") !in included)continue;val p=JSONObject().put("id",capture.getString("id")).put("resourceId",body.getString("resourceId")).put("targetTitle",source.optString("targetTitle","Imported target")).put("targetType",source.optString("targetType","note"));for(k in listOf("comment","quote","context","locator"))p.put(k,body.opt(k)?:JSONObject.NULL);for(k in listOf("author","createdAt","updatedAt","status"))p.put(k,receipt.get(k));portableReviews.put(p)}
  val workspace=JSONObject().put("resources",resources).put("tags",JSONArray(tags.values.toList())).put("settings",JSONObject().put("maxOpenNotes",2).put("openBehavior","split").put("autosaveDelay",0).put("focusMode",false)).put("organization",JSONObject().put("collections",subset).put("favorites",JSONArray(included.filterValues {it.optBoolean("favorite")}.keys.toList()))).put("reviews",portableReviews)
  val hashes=JSONObject();room(total+20*1048576);FileOutputStream(part).use {output->ZipOutputStream(output).use {zip->fun bytes(name:String,data:ByteArray){require(data.size<=20*1048576);room(data.size.toLong());hashes.put(name,MessageDigest.getInstance("SHA-256").digest(data).joinToString(""){"%02x".format(it)});zip.putNextEntry(ZipEntry(name));zip.write(data);zip.closeEntry()}
   bytes("partial.json",coverage.toString().toByteArray());if(request.getString("format")=="markdown"){for(n in 0 until resources.length()){val r=resources.getJSONObject(n);if(r.getString("type")=="note"){bytes("notes/"+r.getString("id")+".json",r.getJSONObject("content").toString().toByteArray());bytes("notes/"+r.getString("id")+".md",("# "+r.getString("title")+"\n\n"+markdown(r.getJSONObject("content"),types=included.mapValues {it.value.getString("type")})).toByteArray())}}}else bytes("workspace.json",workspace.toString().toByteArray());for((name,f)in binaries){guard(row);hashes.put(name,hash(f));zip.putNextEntry(ZipEntry(name));f.inputStream().use {input->val b=ByteArray(65536);while(true){guard(row);val n=input.read(b);if(n<0)break;room(n.toLong());zip.write(b,0,n)}};zip.closeEntry()};bytes("manifest.json",JSONObject().put("version",if(request.getString("format")=="markdown")1 else 6).put("kind",if(request.getString("format")=="markdown")"vaultor-markdown-reading" else "vaultor-partial").put("createdAt",java.time.Instant.now().toString()).put("resources",resources.length()).put("tags",tags.size).put("checksums",JSONObject(hashes.toString())).toString().toByteArray());zip.finish();output.fd.sync()}}
  guard(row);require(part.length()<=MAX);val digest=hash(part);check(part.renameTo(artifact(id)));row.put("filename",if(request.getString("format")=="markdown")"vaultor-partial-markdown.zip" else "vaultor-partial.zip").put("mime","application/zip").put("bytes",artifact(id).length()).put("sha256",digest).put("coverage",coverage).put("detail","Verified partial package ready · "+included.size+" resources · "+coverage.getJSONArray("omissions").length()+" omissions").put("state","ready");save(row)
 }}
 internal fun markdown(node:JSONObject,depth:Int=0,types:Map<String,String> = emptyMap()):String {
  require(depth<=64);val children=node.optJSONArray("content")?:JSONArray();val text=(0 until children.length()).joinToString(""){markdown(children.getJSONObject(it),depth+1,types)};val attrs=node.optJSONObject("attrs")?:JSONObject()
  fun escaped(value:String)=value.replace("\\","\\\\").replace("*","\\*").replace("_","\\_").replace("[","\\[")
  return when(node.optString("type")){
   "text"->{var out=escaped(node.optString("text"));val marks=node.optJSONArray("marks")?:JSONArray();for(n in 0 until marks.length()){val mark=marks.getJSONObject(n);out=when(mark.optString("type")){"bold"->"**"+out+"**";"italic"->"*"+out+"*";"strike"->"~~"+out+"~~";"code"->"\u0060"+node.optString("text").replace("\u0060","\\\u0060")+"\u0060";"link"->{val href=mark.optJSONObject("attrs")?.optString("href").orEmpty();if(href.startsWith("https://")||href.startsWith("http://"))"["+out+"]("+href.replace("(","%28").replace(")","%29")+")"else out};else->out}};out}
   "paragraph"->text+"\n\n"
   "heading"->"#".repeat(attrs.optInt("level",1).coerceIn(1,6))+" "+text+"\n\n"
   "hardBreak"->"  \n"
   "horizontalRule"->"\n---\n"
   "listItem"->"- "+text
   "blockquote"->text.trimEnd().lines().joinToString("\n"){"> "+it}+"\n\n"
   "codeBlock"->{val raw=(0 until children.length()).joinToString(""){children.getJSONObject(it).optString("text")};val fence="\u0060".repeat(maxOf(3,(Regex("\u0060+").findAll(raw).maxOfOrNull {it.value.length}?:0)+1));fence+"\n"+raw+"\n"+fence+"\n\n"}
   "resourceLink"->{val id=attrs.optString("resourceId");val label=escaped(attrs.optString("label",attrs.optString("title","Linked resource")));if(id in types)"["+label+"]("+(if(types[id]=="note")id+".md" else "../files/"+id)+")"else label+" (not included: "+id+")"}
   "image"->{val id=attrs.optString("resourceId");if(types[id]=="file")"!["+escaped(attrs.optString("alt"))+"](../files/"+id+")\n"else "[Image not included: "+escaped(attrs.optString("alt",id))+"]\n"}
   "tableCell","tableHeader"->text.trim().replace("\n"," / ")+" | "
   "tableRow"->"| "+text+"\n"
   else->text
  }
 }
 private fun verified(id:String):Pair<JSONObject,File>{val row=item(id);localIdentity(row.getJSONObject("source"));require(row.getString("state")=="ready"&&!companions.isLocked(row.getString("scope"))){"No available verified export"};val f=artifact(id);require(f.length()==row.getLong("bytes")&&hash(f)==row.getString("sha256")){"Export artifact changed; prepare it again"};companions.requireAccess(row.getString("scope"));return row to f}
 fun handoff(id:String,share:Boolean){worker.execute {try{val (row,f)=verified(id);if(share){val folder=File(ctx.cacheDir,"media-share").apply {mkdirs()};val shared=File(folder,"export-$id-"+safeName(row.getString("filename")));require(folder.usableSpace>f.length()+16L*1048576);f.copyTo(shared,true);val uri=FileProvider.getUriForFile(ctx,ctx.packageName+".media",shared);val intent=Intent(Intent.ACTION_SEND).setType(row.getString("mime")).putExtra(Intent.EXTRA_STREAM,uri).apply {clipData=ClipData.newRawUri("Export",uri)}.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);android.os.Handler(ctx.mainLooper).post {try{companions.requireAccess(row.getString("scope"));ctx.startActivity(Intent.createChooser(intent,"Share verified export").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK))}catch(_:Exception){row.put("detail","No compatible sharing application. Use Save instead.");save(row)}}}else {check(outputPrefs.edit().putString("pending",id).commit());android.os.Handler(ctx.mainLooper).post {try{val activity=activityProvider?.invoke()?:error("Open Vaultor first");companions.requireAccess(row.getString("scope"));activity.startActivityForResult(Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType(row.getString("mime")).putExtra(Intent.EXTRA_TITLE,row.getString("filename")),7409)}catch(_:Exception){outputPrefs.edit().remove("pending").commit();row.put("detail","Save picker unavailable; artifact retained");save(row)}}}}catch(e:Exception){val row=item(id);row.put("detail",(e.message?:"Export handoff failed; artifact retained").take(200));save(row)}}}
 var activityProvider:(()->android.app.Activity?)?=null
 fun output(result:Int,data:Intent?){val id=outputPrefs.getString("pending",null)?:return;outputPrefs.edit().remove("pending").commit();if(result!=android.app.Activity.RESULT_OK||data?.data==null)return;val uri=data.data!!;worker.execute {try{val (row,f)=verified(id);require(uri.scheme=="content");ctx.contentResolver.openOutputStream(uri,"wt")?.use {out->f.inputStream().use {input->val b=ByteArray(65536);while(true){companions.requireAccess(row.getString("scope"));val n=input.read(b);if(n<0)break;out.write(b,0,n)}};companions.requireAccess(row.getString("scope"))}?:error("Destination unavailable");row.put("detail","Verified bytes handed to the selected provider. Export remains available.");save(row)}catch(_:Exception){val row=item(id);row.put("detail","Provider copy failed. Verified export retained; choose Save again.");save(row)}}}
}
